import { WORKBENCH_COLOR_SOURCES } from "./vscode-theme-sources.mjs";
import {
  mapSyntaxAccentColors,
  normalizeAccentColor,
  pickSyntaxDangerColor,
} from "./vscode-syntax-accents.mjs";
import { SYNTAX_ACCENT_ORDER } from "./vscode-theme-sources.mjs";

const TEXT_THEME_VARS = new Set(["--text-primary", "--text-secondary", "--text-muted"]);

function isTransparentWorkbenchColor(value) {
  const trimmed = value.trim();
  if (!trimmed.startsWith("#")) return false;
  const hex = trimmed.slice(1);
  if (hex.length === 8) {
    const alpha = Number.parseInt(hex.slice(6, 8), 16);
    return !Number.isNaN(alpha) && alpha < 255;
  }
  return false;
}

export function pickColor(colors, keys, options) {
  for (const key of keys) {
    const value = colors[key];
    if (!value?.trim()) continue;
    const trimmed = value.trim();
    if (options?.skipTransparent && isTransparentWorkbenchColor(trimmed)) continue;
    return trimmed;
  }
  return undefined;
}

function accentBorderFromPrimary(accentPrimary) {
  const hex = accentPrimary.replace("#", "");
  if (hex.length === 6) return `#${hex}1f`;
  return undefined;
}

export function mapVscodeColorsToDryl(colors) {
  const mapped = {};
  for (const [drylVar, sources] of Object.entries(WORKBENCH_COLOR_SOURCES)) {
    const value = pickColor(colors, sources, {
      skipTransparent: TEXT_THEME_VARS.has(drylVar),
    });
    if (value) mapped[drylVar] = value;
  }
  return mapped;
}

export function mapVscodeThemeToDryl(theme) {
  const colors = theme.colors ?? {};
  const textPrimary = pickColor(colors, ["editor.foreground", "foreground"]);
  const mapped = mapVscodeColorsToDryl(colors);
  if (!mapped["--danger-primary"]) {
    const syntaxDanger = pickSyntaxDangerColor(theme, textPrimary);
    if (syntaxDanger) mapped["--danger-primary"] = syntaxDanger;
  }
  const used = new Set(
    Object.values(mapped)
      .map((value) => normalizeAccentColor(value)?.toLowerCase())
      .filter(Boolean),
  );
  const syntaxAccents = mapSyntaxAccentColors(theme, used, textPrimary);
  for (const token of SYNTAX_ACCENT_ORDER) {
    const value = syntaxAccents[token];
    if (value) mapped[token] = value;
  }
  if (mapped["--accent-primary"]) {
    mapped["--accent-border"] =
      accentBorderFromPrimary(mapped["--accent-primary"]) ??
      pickColor(colors, ["focusBorder", "contrastBorder"]) ??
      mapped["--accent-border"];
  } else if (!mapped["--accent-border"]) {
    mapped["--accent-border"] = pickColor(colors, ["focusBorder", "contrastBorder"]);
  }
  return mapped;
}

/** @deprecated alias */
export const mapVscodeColorsToDrylScss = mapVscodeColorsToDryl;
/** @deprecated alias */
export const mapVscodeThemeToDrylScss = mapVscodeThemeToDryl;
